import type { Product } from './products'

// The cart is stored entirely in the URL as a single `cart` search param.
// The format is a compact, comma-separated list of `<id>x<qty>` pairs, e.g.
//
//     ?cart=2x1,5x3
//
// This keeps URLs readable while being easy to parse/serialize. The router's
// `validateSearch` (see router.ts) parses this string into a structured value
// and serializes it back when navigating.

export type CartItems = Record<number, number> // { [productId]: quantity }

/** Parse a `cart` URL param string like "2x1,5x3" into a CartItems map. */
export function parseCartParam(raw: unknown): CartItems {
  const cart: CartItems = {}
  if (typeof raw !== 'string' || raw.length === 0) return cart

  for (const part of raw.split(',')) {
    const [idStr, qtyStr] = part.split('x')
    const id = Number(idStr)
    const qty = Number(qtyStr)
    if (Number.isInteger(id) && id > 0 && Number.isInteger(qty) && qty > 0) {
      cart[id] = qty
    }
  }
  return cart
}

/** Serialize a CartItems map into a `cart` URL param string. */
export function serializeCartParam(cart: CartItems): string {
  return Object.entries(cart)
    .map(([id, qty]) => `${id}x${qty}`)
    .join(',')
}

export type CartLine = {
  product: Product
  quantity: number
  subtotal: number
}

/** Combine a cart map with the product catalog to produce displayable lines. */
export function buildCartLines(cart: CartItems, products: Product[]): CartLine[] {
  const lines: CartLine[] = []
  for (const product of products) {
    const quantity = cart[product.id]
    if (quantity) {
      lines.push({
        product,
        quantity,
        subtotal: product.price * quantity,
      })
    }
  }
  return lines
}

export function cartTotal(lines: CartLine[]): number {
  return lines.reduce((sum, l) => sum + l.subtotal, 0)
}

export function cartCount(cart: CartItems): number {
  return Object.values(cart).reduce((sum, q) => sum + q, 0)
}

import {
  createRouter,
  createRootRoute,
  createRoute,
  Outlet,
  redirect,
} from '@tanstack/react-router'
import { App } from './App'
import { parseCartParam, serializeCartParam, type CartItems } from './cart'

// ---------------------------------------------------------------------------
// Route tree
// ---------------------------------------------------------------------------
//
// We use a single index route. Its `validateSearch` is where the magic happens:
// it parses the `cart` URL search param (e.g. `?cart=2x1,5x3`) into a typed
// `CartItems` object, and the route's `search` middlewares take care of
// serializing changes back into the URL whenever we navigate.

const rootRoute = createRootRoute({
  component: () => <Outlet />,
})

type CartSearch = {
  cart: string
}

const indexRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/',
  component: App,
  // Parse the incoming `?cart=...` search param. Anything that isn't a valid
  // cart string is normalized to an empty string, which represents an empty
  // cart. This guarantees the search state is always well-formed.
  validateSearch: (input: Record<string, unknown>): CartSearch => {
    const raw = input.cart
    return {
      cart: typeof raw === 'string' ? raw : '',
    }
  },
  // When navigating, only keep keys we recognize (just `cart`) so that stray
  // params don't accumulate, and ensure the value is always a string.
  search: {
    middlewares: [
      ({ search, next }) => {
        const normalized: CartSearch = {
          cart: typeof search.cart === 'string' ? search.cart : '',
        }
        return next(normalized)
      },
    ],
  },
  // If the user lands on a non-`/` path, send them to the index so the cart
  // search param has a home.
  beforeLoad: ({ location }) => {
    if (location.pathname !== '/') {
      throw redirect({ to: '/', search: { cart: '' } })
    }
  },
})

const routeTree = rootRoute.addChildren([indexRoute])

// ---------------------------------------------------------------------------
// Router instance
// ---------------------------------------------------------------------------

export const router = createRouter({
  routeTree,
  defaultPreload: 'intent',
})

// ---------------------------------------------------------------------------
// Helpers for reading / writing cart state from the URL
// ---------------------------------------------------------------------------

/** Read the current cart map from the router's search state. */
export function getCartFromSearch(search: { cart: string }): CartItems {
  return parseCartParam(search.cart)
}

/**
 * Build the next search object for a given cart map, preserving any other
 * (currently none) search params. Returns a fresh object so navigation is
 * always triggered.
 */
export function searchForCart(
  current: { cart: string },
  cart: CartItems,
): CartSearch {
  return {
    ...current,
    cart: serializeCartParam(cart),
  }
}

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router
  }
}

import React from 'react'
import ReactDOM from 'react-dom/client'
import { RouterProvider } from '@tanstack/react-router'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { router } from './router'
import './styles.css'

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 60 * 1000,
      retry: 1,
    },
  },
})

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <RouterProvider router={router} />
    </QueryClientProvider>
  </React.StrictMode>,
)

import { useQuery } from '@tanstack/react-query'
import { useSearch, useNavigate } from '@tanstack/react-router'
import { fetchProducts } from './products'
import {
  getCartFromSearch,
  searchForCart,
} from './router'
import {
  buildCartLines,
  cartTotal,
  cartCount,
  type CartItems,
} from './cart'
import { ProductCard } from './components/ProductCard'
import { CartPanel } from './components/CartPanel'

export function App() {
  const search = useSearch({ from: '/' })
  const navigate = useNavigate()

  // Fetch the product catalog with TanStack Query.
  const productsQuery = useQuery({
    queryKey: ['products'],
    queryFn: fetchProducts,
  })

  // The single source of truth for the cart: the URL search params.
  const cart = getCartFromSearch(search)
  const products = productsQuery.data ?? []
  const cartLines = buildCartLines(cart, products)
  const total = cartTotal(cartLines)
  const count = cartCount(cart)

  // Update the cart map and write it back to the URL. Because the cart lives
  // entirely in the search params, this is all that's required to persist a
  // change — a refresh will restore the exact same state.
  function updateCart(next: CartItems) {
    navigate({
      to: '/',
      search: searchForCart(search, next),
      replace: false,
    })
  }

  function addToCart(productId: number) {
    const next = { ...cart, [productId]: (cart[productId] ?? 0) + 1 }
    updateCart(next)
  }

  function decrement(productId: number) {
    const next = { ...cart }
    const current = next[productId] ?? 0
    if (current <= 1) {
      delete next[productId]
    } else {
      next[productId] = current - 1
    }
    updateCart(next)
  }

  function increment(productId: number) {
    updateCart({ ...cart, [productId]: (cart[productId] ?? 0) + 1 })
  }

  function removeFromCart(productId: number) {
    const next = { ...cart }
    delete next[productId]
    updateCart(next)
  }

  function clearCart() {
    updateCart({})
  }

  return (
    <div className="app">
      <header className="app-header">
        <h1>
          <span className="logo">🛒</span> Shoppy
        </h1>
        <div className="header-cart">
          <span className="cart-badge">{count}</span>
          <span className="cart-total">${total.toFixed(2)}</span>
        </div>
      </header>

      <main className="app-main">
        <section className="products-section">
          <div className="section-head">
            <h2>Products</h2>
            {productsQuery.isLoading && <span className="muted">Loading…</span>}
            {productsQuery.isError && (
              <span className="error">Failed to load products.</span>
            )}
          </div>

          {productsQuery.isLoading ? (
            <div className="grid">
              {Array.from({ length: 6 }).map((_, i) => (
                <div className="card skeleton" key={i} />
              ))}
            </div>
          ) : (
            <div className="grid">
              {products.map((p) => (
                <ProductCard
                  key={p.id}
                  product={p}
                  quantity={cart[p.id] ?? 0}
                  onAdd={() => addToCart(p.id)}
                />
              ))}
            </div>
          )}
        </section>

        <aside className="cart-section">
          <CartPanel
            lines={cartLines}
            total={total}
            count={count}
            onIncrement={increment}
            onDecrement={decrement}
            onRemove={removeFromCart}
            onClear={clearCart}
          />
        </aside>
      </main>

      <footer className="app-footer">
        <p>
          Cart state is stored entirely in the URL. Try refreshing the page —
          your cart will be restored.
        </p>
      </footer>
    </div>
  )
}

import type { Product } from '../products'

type Props = {
  product: Product
  quantity: number
  onAdd: () => void
}

export function ProductCard({ product, quantity, onAdd }: Props) {
  return (
    <div className="card">
      <div className="card-image">{product.image}</div>
      <div className="card-body">
        <span className="card-category">{product.category}</span>
        <h3 className="card-name">{product.name}</h3>
        <p className="card-desc">{product.description}</p>
        <div className="card-footer">
          <span className="card-price">${product.price.toFixed(2)}</span>
          <button
            className="btn btn-primary"
            onClick={onAdd}
            disabled={quantity > 0}
          >
            {quantity > 0 ? `In cart (${quantity})` : 'Add to Cart'}
          </button>
        </div>
      </div>
    </div>
  )
}

:root {
  --bg: #f5f6fa;
  --surface: #ffffff;
  --text: #1a1a2e;
  --muted: #6b7280;
  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --primary-soft: #eef2ff;
  --danger: #ef4444;
  --border: #e5e7eb;
  --radius: 12px;
  --shadow: 0 1px 3px rgba(0, 0, 0, 0.06), 0 1px 2px rgba(0, 0, 0, 0.04);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.app {
  max-width: 1200px;
  margin: 0 REDACTED;
  padding: 0 20px 40px;
}

/* Header */
.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 0;
  position: sticky;
  top: 0;
  background: var(--bg);
  z-index: 10;
}

.app-header h1 {
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.logo {
  margin-right: 6px;
}

.header-cart {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--surface);
  padding: 8px 16px;
  border-radius: 999px;
  box-shadow: var(--shadow);
}

.cart-badge {
  background: var(--primary);
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  min-width: 24px;
  height: 24px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 6px;
}

.cart-total {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

/* Main layout */
.app-main {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 28px;
  align-items: start;
}

@media (max-width: 900px) {
  .app-main {
    grid-template-columns: 1fr;
  }
}

.section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.section-head h2 {
  font-size: 20px;
  font-weight: 700;
}

.muted {
  color: var(--muted);
  font-size: 14px;
}

.error {
  color: var(--danger);
  font-size: 14px;
}

/* Product grid */
.grid {
  display: grid;
  grid-template-columns: repeat(REDACTED-fill, minmax(220px, 1fr));
  gap: 18px;
}

.card {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.card:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.08);
}

.card-image {
  font-size: 56px;
  height: 130px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #f0f4ff, #faf5ff);
}

.card-body {
  padding: 14px 16px 16px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.card-category {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--primary);
  font-weight: 700;
}

.card-name {
  font-size: 16px;
  font-weight: 600;
  margin: 4px 0 6px;
}

.card-desc {
  font-size: 13px;
  color: var(--muted);
  flex: 1;
  margin-bottom: 14px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-price {
  font-weight: 800;
  font-size: 17px;
  font-variant-numeric: tabular-nums;
}

/* Skeleton */
.skeleton {
  height: 280px;
  background: linear-gradient(90deg, #eceef2 25%, #f5f6fa 37%, #eceef2 63%);
  background-size: 400% 100%;
  animation: shimmer 1.4s ease infinite;
}

@keyframes shimmer {
  0% { background-position: 100% 0; }
  100% { background-position: 0 0; }
}

/* Cart panel */
.cart-panel {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 20px;
  position: sticky;
  top: 80px;
}

.cart-panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border);
}

.cart-panel-head h2 {
  font-size: 18px;
  font-weight: 700;
}

.cart-empty {
  text-align: center;
  padding: 40px 16px;
}

.cart-empty-icon {
  font-size: 48px;
  margin-bottom: 12px;
}

.cart-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 14px;
  max-height: 420px;
  overflow-y: REDACTED;
  padding-right: 4px;
}

.cart-item {
  display: grid;
  grid-template-columns: REDACTED 1fr REDACTED REDACTED REDACTED;
  align-items: center;
  gap: 10px;
}

.cart-item-image {
  font-size: 26px;
  width: 40px;
  text-align: center;
}

.cart-item-info {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.cart-item-name {
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cart-item-price {
  font-size: 12px;
  color: var(--muted);
}

.cart-item-subtotal {
  font-weight: 700;
  font-size: 14px;
  font-variant-numeric: tabular-nums;
  min-width: 56px;
  text-align: right;
}

.qty-controls {
  display: flex;
  align-items: center;
  gap: 6px;
}

.qty {
  font-weight: 700;
  min-width: 20px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}

/* Buttons */
.btn {
  border: none;
  cursor: pointer;
  font-family: inherit;
  font-weight: 600;
  border-radius: 8px;
  transition: background 0.15s ease, transform 0.1s ease;
}

.btn:active {
  transform: scale(0.97);
}

.btn:disabled {
  cursor: default;
  opacity: 0.85;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
  padding: 9px 14px;
  font-size: 13px;
}

.btn-primary:not(:disabled):hover {
  background: var(--primary-hover);
}

.btn-secondary {
  background: var(--primary-soft);
  color: var(--primary);
  padding: 10px 16px;
  font-size: 14px;
  width: 100%;
}

.btn-secondary:hover {
  background: #e0e7ff;
}

.btn-icon {
  background: var(--primary-soft);
  color: var(--primary);
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  line-height: 1;
}

.btn-icon:hover {
  background: #e0e7ff;
}

.btn-remove {
  background: transparent;
  color: var(--muted);
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
}

.btn-remove:hover {
  color: var(--danger);
  background: #fef2f2;
}

/* Summary */
.cart-summary {
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.cart-total-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 16px;
  font-weight: 700;
}

.cart-total-value {
  font-size: 20px;
  font-variant-numeric: tabular-nums;
}

/* Footer */
.app-footer {
  margin-top: 40px;
  text-align: center;
  color: var(--muted);
  font-size: 13px;
}
